   264      public void serializeWithType(Object bean, JsonGenerator gen, SerializationContext ctxt,
   265              TypeSerializer typeSer0) throws JacksonException
   266      {
   267          // Regardless of other parts, first need to find value to serialize:
   268          Object value;
   269          try {
   270              value = _accessor.getValue(bean);
   271          } catch (Exception e) {
   272              wrapAndThrow(ctxt, e, bean, _accessor.getName() + "()");
   273              return; // never gets here
   274          }
   275          // and if we got null, can also just write it directly
   276          if (value == null) {
   277              ctxt.defaultSerializeNullValue(gen);
   278              return;
   279          }
   280          ValueSerializer<Object> ser = _valueSerializer;
   281          if (ser == null) {
   282              Class<?> cc = value.getClass();
   283              if (_valueType.hasGenericTypes()) {
   284                  ser = _findAndAddDynamic(ctxt, ctxt.constructSpecializedType(_valueType, cc));
   285              } else {
   286                  ser = _findAndAddDynamic(ctxt, cc);
   287              }
   288          }
