   293          // 09-Dec-2010, tatu: To work around natural type's refusal to add type info, we do
   294          //    this (note: type is for the wrapper type, not enclosed value!)
   295          if (_forceTypeInformation) {
   296              // Confusing? Type id is for POJO and NOT for value returned by JsonValue accessor...
   297              WritableTypeId typeIdDef = typeSer0.writeTypePrefix(gen, ctxt,
   298                      typeSer0.typeId(bean, JsonToken.VALUE_STRING));
   299              ser.serialize(value, gen, ctxt);
   300              typeSer0.writeTypeSuffix(gen, ctxt, typeIdDef);
   301              return;
   302          }
